UPDATE services_content SET draft_json = '{"name":"אוטומציות עסקיות","short":"אוטומציות","lead":"העבודה השחורה רצה לבד ברקע. אתם נשארים עם ההחלטות.","pain":"כל משימה שאתם עושים יותר מפעם ביום יכולה לקרות בלי אתם. ליד נכנס? הוא מקבל הודעה, נפתחת משימה, והפרטים כבר מחכים לכם. בלי קליק אחד.","points":["מה שחוזר כל שבוע רץ בלי אתם","אתם קובעים את הכללים, המערכת מבצעת","מה שדורש ראש מגיע אליכם"],"h1a":"אל תעבדו בשביל המערכות.","h1b":"שהן יעבדו בשבילכם.","pageLead":"משימות שחוזרות על עצמן שורפות את הזמן שלכם ושל הצוות. נחבר את הכלים שכבר יש לכם, כדי שהעבודה השחורה תרוץ לבד. ומה שדורש ראש? מגיע אליכם.","symptomsTitle":"איפה זה עוזר הכי הרבה","symptoms":["להעתיק פרטים ממערכת אחת לשנייה, כל יום מחדש","לשלוח הודעת אישור או מעקב אחרי כל פנייה","תזכורות שתלויות בזה שמישהו יזכור","לעדכן טבלאות ורשימות ביד"],"buildTitle":"איך זה עובד","build":[{"t":"קורה משהו","d":"נכנסת פנייה, מתקבל תשלום, מגיע תאריך, משתנה סטטוס."},{"t":"המערכת בודקת את הכללים שקבעתם","d":"בלי ניחושים. בדיוק מה שהוגדר מראש, ורק במקרים שהוגדרו מראש."},{"t":"הפעולה רצה","d":"ההודעה נשלחת, הרשומה מתעדכנת, המשימה נפתחת. בלי שנגעתם."},{"t":"וכשצריך אתכם","d":"התהליך עוצר ומגיע למסך שלכם, במקום להמשיך לרוץ לבד."}],"closing":"בואו נראה מה אפשר להפוך לאוטומטי","closingBody":"ספרו לנו מה חוזר על עצמו אצלכם כל שבוע. נגיד בכנות מה שווה להפוך לאוטומטי, ומה עדיף להשאיר ידני.","note":"הדוגמאות כאן ממחישות את העיקרון. מה בדיוק ירוץ אוטומטית אצלכם ייקבע באפיון.","seo":{"title":"אוטומציות עסקיות | LAHAV AI","description":"מעבירים את הפעולות שחוזרות על עצמן למערכת שעושה אותן לבד, ומשאירים לכם את ההחלטות.","ogTitle":"אוטומציות עסקיות | LAHAV AI","ogDescription":"מעבירים את הפעולות שחוזרות על עצמן למערכת שעושה אותן לבד, ומשאירים לכם את ההחלטות.","ogImage":"","noindex":false}}', draft_updated_at = '2026-09-01T23:03:47.311Z' WHERE slug = 'automations';

