UPDATE services_content SET draft_json = '{"name":"יצירת תוכן באמצעות AI","short":"תוכן","lead":"מדף ריק לטיוטה תוך דקות. מה שיוצא החוצה עובר דרככם.","pain":"AI מצוין בלהביא אתכם מאפס לטיוטה שאפשר לעבוד איתה. מה שהוא לא יעשה זה להחליט מה נכון להגיד בשם העסק שלכם. אתם העורכים הסופיים, תמיד.","points":["מתחילים ממה שרוצים להשיג","טיוטה ראשונה מהר","שום דבר לא יוצא בלי אישור שלכם"],"h1a":"מדף ריק לטיוטה,","h1b":"תוך דקות.","pageLead":"הבעיה היא לא חוסר ברעיונות. הבעיה היא הדף הריק. נטמיע אצלכם כלי AI שמייצרים טיוטות לפוסטים, מיילים ומסמכים, ואתם נשארים העורכים הסופיים.","symptomsTitle":"ככה זה נראה ביום יום","symptoms":["יודעים שצריך לכתוב, ואף פעם אין לזה זמן","וכשכבר כותבים, זה יוצא כללי מדי","אין סדר עבודה, אז זה קורה בהתקפים","קשה לשמור על אותו קול לאורך זמן"],"buildTitle":"איך נעבוד","build":[{"t":"מתחילים ממטרה","d":"למי כותבים, ומה אתם רוצים שיקרה אחרי שיסיימו לקרוא."},{"t":"בריף של חמש שורות","d":"נושא, זווית, ומה חייב להופיע. לא מסמך."},{"t":"טיוטה בסיוע AI","d":"יש טקסט על הדף. לא מוכן, אבל אפשר לעבוד איתו."},{"t":"אתם מאשרים","d":"קוראים, מתקנים, מאשרים. רק אז זה יוצא החוצה."}],"closing":"רוצים סדר בתוכן?","closingBody":"נבנה יחד סדר עבודה לתוכן: ממה מתחילים, מי כותב, ומי מאשר לפני שזה יוצא.","note":"התרשים מציג את סדר העבודה. היקף השירות המדויק ייקבע יחד איתכם.","seo":{"title":"יצירת תוכן באמצעות AI | LAHAV AI","description":"תהליך תוכן מסודר: מטרה עסקית, בריף, טיוטה בעזרת AI, בדיקה ואישור שלכם, ורק אז שימוש.","ogTitle":"יצירת תוכן באמצעות AI | LAHAV AI","ogDescription":"תהליך תוכן מסודר: מטרה עסקית, בריף, טיוטה בעזרת AI, בדיקה ואישור שלכם, ורק אז שימוש.","ogImage":"","noindex":false}}', draft_updated_at = '2026-09-01T23:03:47.311Z' WHERE slug = 'ai-content';
